import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { hogFlowsEmailSendingSuspensionRetrieve } from 'products/workflows/frontend/generated/api'
import type { EmailSendingSuspensionStatusApi } from 'products/workflows/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsEmailSuspensionLogicValues {
    currentProjectId: number | null // projectLogic
    emailSendingSuspended: boolean
    emailSendingSuspensionReason: string
    suspensionStatus: EmailSendingSuspensionStatusApi | null
    suspensionStatusLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsEmailSuspensionLogicActions {
    loadSuspensionStatus: () => any
    loadSuspensionStatusFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSuspensionStatusSuccess: (
        suspensionStatus: EmailSendingSuspensionStatusApi | null,
        payload?: any
    ) => {
        suspensionStatus: EmailSendingSuspensionStatusApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowsEmailSuspensionLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        emailSendingSuspended: (suspensionStatus: EmailSendingSuspensionStatusApi | null) => boolean
        emailSendingSuspensionReason: (suspensionStatus: EmailSendingSuspensionStatusApi | null) => string
    }
}

export type workflowsEmailSuspensionLogicType = MakeLogicType<
    workflowsEmailSuspensionLogicValues,
    workflowsEmailSuspensionLogicActions,
    Record<string, any>,
    workflowsEmailSuspensionLogicMeta
>

export const workflowsEmailSuspensionLogic = kea<workflowsEmailSuspensionLogicType>([
    path(['products', 'workflows', 'frontend', 'workflowsEmailSuspensionLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        suspensionStatus: [
            null as EmailSendingSuspensionStatusApi | null,
            {
                loadSuspensionStatus: async () => {
                    if (!values.currentProjectId) {
                        return null
                    }
                    return await hogFlowsEmailSendingSuspensionRetrieve(String(values.currentProjectId))
                },
            },
        ],
    })),
    selectors({
        emailSendingSuspended: [
            (s) => [s.suspensionStatus],
            (status: EmailSendingSuspensionStatusApi | null): boolean => status?.email_sending_suspended ?? false,
        ],
        emailSendingSuspensionReason: [
            (s) => [s.suspensionStatus],
            (status: EmailSendingSuspensionStatusApi | null): string => status?.email_sending_suspension_reason ?? '',
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadSuspensionStatus()
    }),
])
